injectedCss.text:
/* H1: an always-on keyframe that animates scale() forces the compositor to re-raster the layer.
   Drop the scale from both always-on offenders; keep every other property identical. */
@keyframes aurora {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-3%, 2.5%, 0); }
}
.stl-ring { will-change: transform, opacity; }
